    pub fn mark_lists<F: FnMut(&NodeList<'gc>)>(&'gc self, cb: &mut F) {
        match self {
            Node::Program(n) => { cb(&n.body); cb(&n.decorations.get()); cb(&n.dummy_param_list.get()); }
            Node::FunctionExpression(n) => { cb(&n.params); cb(&n.decorations.get()); }
            Node::ArrowFunctionExpression(n) => { cb(&n.params); cb(&n.decorations.get()); }
            Node::FunctionDeclaration(n) => { cb(&n.params); cb(&n.decorations.get()); }
            Node::ComponentDeclaration(n) => { cb(&n.params); cb(&n.decorations.get()); }
            Node::HookDeclaration(n) => { cb(&n.params); cb(&n.decorations.get()); }
            Node::MatchStatement(n) => { cb(&n.cases); }
            Node::BlockStatement(n) => { cb(&n.body); }
            Node::StaticBlock(n) => { cb(&n.body); }
            Node::SwitchStatement(n) => { cb(&n.cases); }
            Node::SequenceExpression(n) => { cb(&n.expressions); }
            Node::ObjectExpression(n) => { cb(&n.properties); }
            Node::ArrayExpression(n) => { cb(&n.elements); }
            Node::NewExpression(n) => { cb(&n.arguments); }
            Node::CallExpression(n) => { cb(&n.arguments); }
            Node::OptionalCallExpression(n) => { cb(&n.arguments); }
            Node::SwitchCase(n) => { cb(&n.consequent); }
            Node::VariableDeclaration(n) => { cb(&n.declarations); }
            Node::TemplateLiteral(n) => { cb(&n.quasis); cb(&n.expressions); }
            Node::ClassDeclaration(n) => { cb(&n.implements); cb(&n.decorators); }
            Node::ClassExpression(n) => { cb(&n.implements); cb(&n.decorators); }
            Node::ClassBody(n) => { cb(&n.body); }
            Node::ClassProperty(n) => { cb(&n.decorators); }
            Node::ClassPrivateProperty(n) => { cb(&n.decorators); }
            Node::MethodDefinition(n) => { cb(&n.decorators); }
            Node::ImportDeclaration(n) => { cb(&n.specifiers); cb(&n.attributes); }
            Node::ExportNamedDeclaration(n) => { cb(&n.specifiers); }
            Node::ObjectPattern(n) => { cb(&n.properties); }
            Node::ArrayPattern(n) => { cb(&n.elements); }
            Node::MatchExpression(n) => { cb(&n.cases); }
            Node::MatchObjectPattern(n) => { cb(&n.properties); }
            Node::MatchArrayPattern(n) => { cb(&n.elements); }
            Node::MatchOrPattern(n) => { cb(&n.patterns); }
            Node::MatchInstanceObjectPattern(n) => { cb(&n.properties); }
            Node::JSXOpeningElement(n) => { cb(&n.attributes); }
            Node::JSXElement(n) => { cb(&n.children); }
            Node::JSXFragment(n) => { cb(&n.children); }
            Node::FunctionTypeAnnotation(n) => { cb(&n.params); }
            Node::HookTypeAnnotation(n) => { cb(&n.params); }
            Node::ComponentTypeAnnotation(n) => { cb(&n.params); }
            Node::TupleTypeAnnotation(n) => { cb(&n.element_types); }
            Node::UnionTypeAnnotation(n) => { cb(&n.types); }
            Node::IntersectionTypeAnnotation(n) => { cb(&n.types); }
            Node::InterfaceTypeAnnotation(n) => { cb(&n.extends); }
            Node::InterfaceDeclaration(n) => { cb(&n.extends); }
            Node::DeclareInterface(n) => { cb(&n.extends); }
            Node::DeclareClass(n) => { cb(&n.extends); cb(&n.implements); cb(&n.mixins); }
            Node::DeclareComponent(n) => { cb(&n.params); }
            Node::DeclareExportDeclaration(n) => { cb(&n.specifiers); }
            Node::ObjectTypeAnnotation(n) => { cb(&n.properties); cb(&n.indexers); cb(&n.call_properties); cb(&n.internal_slots); }
            Node::TypeParameterDeclaration(n) => { cb(&n.params); }
            Node::TypeParameterInstantiation(n) => { cb(&n.params); }
            Node::EnumStringBody(n) => { cb(&n.members); }
            Node::EnumNumberBody(n) => { cb(&n.members); }
            Node::EnumBigIntBody(n) => { cb(&n.members); }
            Node::EnumBooleanBody(n) => { cb(&n.members); }
            Node::EnumSymbolBody(n) => { cb(&n.members); }
            Node::RecordDeclaration(n) => { cb(&n.implements); }
            Node::RecordDeclarationBody(n) => { cb(&n.elements); }
            Node::RecordExpressionProperties(n) => { cb(&n.properties); }
            Node::TSFunctionType(n) => { cb(&n.params); }
            Node::TSConstructorType(n) => { cb(&n.params); }
            Node::TSTupleType(n) => { cb(&n.element_types); }
            Node::TSInterfaceDeclaration(n) => { cb(&n.extends); }
            Node::TSInterfaceBody(n) => { cb(&n.body); }
            Node::TSEnumDeclaration(n) => { cb(&n.members); }
            Node::TSModuleBlock(n) => { cb(&n.body); }
            Node::TSTypeParameterDeclaration(n) => { cb(&n.params); }
            Node::TSTypeParameterInstantiation(n) => { cb(&n.params); }
            Node::TSUnionType(n) => { cb(&n.types); }
            Node::TSIntersectionType(n) => { cb(&n.types); }
            Node::TSTypeLiteral(n) => { cb(&n.members); }
            Node::TSMethodSignature(n) => { cb(&n.params); }
            Node::TSIndexSignature(n) => { cb(&n.parameters); }
            Node::TSCallSignatureDeclaration(n) => { cb(&n.params); }
            _ => {}
        }
    }
